card" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#FFFFFF; border:1px solid #E6DDCC; border-radius:9px; margin:26px 0 0;"><tr><td style="padding:16px 20px;"><p class="ink3" style="margin:0 0 8px; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; line-height:1.5; color:#8C8578;">This invitation expires in 7 days. If the button doesn&#8217;t work, copy and paste this link into your browser:</p><p style="margin:0; font-family:'IBM Plex Mono', ui-monospace, SFMono-Regular, 'Courier New', monospace; font-size:12px; line-height:1.6; word-break:break-all;"><a href="{{action_link}}" style="color:#4E7A66; text-decoration:underline;">{{action_link}}</a></p></td></tr></table><p class="ink2" style="margin:22px 0 0; font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:16px; font-style:italic; color:#4B463E;">— The Patina team</p></td></tr></table>
        </td></tr>
        <tr><td class="px" style="padding:34px 40px 0;">
          <div class="hairbg" style="height:1px; background:#E6DDCC; font-size:0; line-height:0;">&nbsp;</div>
        </td></tr>
        <tr><td class="px" style="padding:22px 40px 32px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
            <td align="left" valign="top">
              <div class="ink2" style="font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:15px; color:#4B463E; margin-bottom:5px;">Patina</div>
              <div class="ink3" style="font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; line-height:1.5; color:#8C8578;">A workshop for interior designers<br>and the makers they trust.</div>
            </td>
            <td align="right" valign="top" class="ink3" style="font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; line-height:1.95; color:#8C8578;">
              <a href="{{dashboard_url}}" style="color:#4E7A66; text-decoration:none;">Dashboard</a><br>
              <a href="{{help_url}}" style="color:#4E7A66; text-decoration:none;">Help center</a><br>
              <a href="{{prefs_url}}" style="color:#4E7A66; text-decoration:none;">Email preferences</a>
            </td>
          </tr></table>
        </td></tr>
      </table>
      <!--[if mso]></td></tr></table><![endif]-->
      <table role="presentation" class="container" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px; max-width:600px;">
        <tr><td class="px" align="center" style="padding:18px 40px 10px; font-family:'IBM Plex Mono', ui-monospace, SFMono-Regular, 'Courier New', monospace; font-size:11px; line-height:1.8; letter-spacing:0.03em; color:#8C8578;">
          Patina &nbsp;·&nbsp; {{business_address}}<br>
